const modal=$('#about');for(const id of ['aboutButton','dataButton'])$('#'+id).onclick=()=>modal.showModal();$('#closeAbout').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
$('#connectomeData').innerHTML=evidence?`<div class="data-note"><strong>Реальный фрагмент: LC4 → DNp01</strong><table><thead><tr><th>Тип</th><th>Клеток в каталоге</th></tr></thead><tbody><tr><td>LC4</td><td>126</td></tr><tr><td>DNp01</td><td>2</td></tr></tbody></table><p>6 362 направленных синаптических контакта суммарно; 50,49206 на одну исходную клетку LC4. Агрегированная связь типов, не измерение силы сигнала.</p><a href="${evidence.source}" target="_blank" rel="noreferrer">Проверить в Cell Type Explorer ↗</a></div><p style="margin-top:15px">Зрительный путь: LC4* → DNp01* → модельный моторный блок. Звёздочка означает расчётную активность. Коэффициент w = ln(1 + 6362) / 10 ≈ ${sim.visualGain.toFixed(3)}; τ LC4 = 0,12 с, τ DNp01 = 0,18 с. Нормировка, постоянные времени и роль в управлении заданы для демонстрации. Остальные каналы — абстрактные блоки.</p><p>Запах: exp(−расстояние / 280). Зрительный стимул: max(0, 1 − расстояние / 380). Угроза конкурирует с пищей и светом; касание и близкие барьеры имеют приоритет. Температура меняет скорость глобально; температурного градиента нет.</p><p>Встроен локальный снимок одной связи из официального каталога. Полный граф не загружен. Live API neuPrint не подключён: он требует личный токен. Токены приложение не запрашивает.</p>`:'<p>Не удалось загрузить справочный фрагмент. Арена работает с демонстрационным коэффициентом; статус источника не подтверждён.</p>';
const eb=document.createElement('button');eb.className='evidence-link';eb.textContent=evidence?'LC4 → DNp01 · 6 362 контакта ↗':'Данные не загружены ↗';eb.onclick=()=>modal.showModal();$('.neural').append(eb);
const canvas=$('#arena'),ctx=canvas.getContext('2d'),chart=$('#chart'),cg=chart.getContext('2d');let cw=0,ch=0,scale=1,ox=0,oy=0;
function fit(c){const r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d)}c.getContext('2d').setTransform(d,0,0,d,0,0);return [r.width,r.height]}
function circle(x,y,r,color,fill=false){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(fill){ctx.fillStyle=color;ctx.fill()}else{ctx.strokeStyle=color;ctx.stroke()}}
function label(t,x,y,color='#98adbb'){ctx.font=`${Math.max(16,10/scale)}px "IBM Plex Mono",monospace`;ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(t,x,y)}
function draw(){[cw,ch]=fit(canvas);ctx.clearRect(0,0,cw,ch);scale=Math.min(cw/W,ch/H);$(".arena-scale span").style.width=(100*scale)+"px";ox=(cw-W*scale)/2;oy=(ch-H*scale)/2;ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.strokeStyle='#1d2b37';ctx.lineWidth=1/scale;
 for(let x=0;x<=W;x+=50){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=0;y<=H;y+=50){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.strokeStyle='#344755';ctx.strokeRect(1,1,W-2,H-2);
 if(sim.light){const glow=ctx.createRadialGradient(820,95,5,820,95,250);glow.addColorStop(0,'#f3d56b35');glow.addColorStop(1,'#f3d56b00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);circle(820,95,15,'#f5d877',true);label('СВЕТ',820,135,'#ddc677')}
 for(const o of sim.objects){if(o.kind==='food'){const grad=ctx.createRadialGradient(o.x,o.y,10,o.x,o.y,180);grad.addColorStop(0,'#61d4a521');grad.addColorStop(1,'#61d4a500');circle(o.x,o.y,180,grad,true);circle(o.x,o.y,45,'#3d7d6355');circle(o.x,o.y,95,'#3d7d6328');ctx.font=`${Math.max(34,24/scale)}px "Segoe UI Emoji",sans-serif`;ctx.textAlign='center';ctx.fillText('🍎',o.x,o.y+12);label('ЕДА',o.x,o.y+48,'#82c7a5')}
  if(o.kind==='obstacle'){ctx.fillStyle='#2c3947';ctx.fillRect(o.x-55,o.y-35,110,70);ctx.strokeStyle='#5b6c7a';ctx.strokeRect(o.x-55,o.y-35,110,70);ctx.save();ctx.beginPath();ctx.rect(o.x-55,o.y-35,110,70);ctx.clip();ctx.strokeStyle='#59697855';for(let k=-100;k<180;k+=13){ctx.beginPath();ctx.moveTo(o.x-55+k,o.y-35);ctx.lineTo(o.x-125+k,o.y+35);ctx.stroke()}ctx.restore()}
  if(o.kind==='object'){circle(o.x,o.y,18,'#a195ef',true);circle(o.x,o.y,29,'#a195ef44');label('↗',o.x,o.y+6,'#171226');label('ОБЪЕКТ',o.x,o.y+50,'#b3a8e9')}}
 if(trail&&sim.path.length>1){ctx.beginPath();sim.path.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#60dfc562';ctx.lineWidth=2;ctx.stroke()}
 if(sim.predator){circle(sim.hunter.x,sim.hunter.y,90,'#ec7a8a15',true);circle(sim.hunter.x,sim.hunter.y,28,'#ec7a8a');label('◇',sim.hunter.x,sim.hunter.y+9,'#ff8d9b');label('ХИЩНИК',sim.hunter.x,sim.hunter.y+52,'#ec7a8a')}
 const f=sim.fly;ctx.save();ctx.translate(f.x,f.y);ctx.rotate(f.angle);ctx.beginPath();ctx.moveTo(0,0);ctx.arc(0,0,83,-.48,.48);ctx.closePath();ctx.fillStyle='#60dfc509';ctx.fill();ctx.strokeStyle='#60dfc530';ctx.stroke();ctx.beginPath();ctx.moveTo(27,0);ctx.lineTo(46,0);ctx.strokeStyle='#60dfc5';ctx.stroke();ctx.restore();circle(f.x,f.y,32,'#60dfc55a');ctx.font=`${Math.max(38,26/scale)}px "Segoe UI Emoji",sans-serif`;ctx.textAlign='center';ctx.fillText('🪰',f.x,f.y+13);label('AGENT 01',f.x,f.y+61,'#9cbfb8');
 if(pulse&&performance.now()-pulse.t<650){const t=(performance.now()-pulse.t)/650;circle(pulse.x,pulse.y,15+t*65,`rgba(123,223,207,${1-t})`)}
 if(cursor){ctx.setLineDash([5,5]);circle(cursor.x,cursor.y,tool==='touch'?65:22,'#c2d6df70');ctx.setLineDash([])}ctx.restore();drawChart()}
function drawChart(){const [w,h]=fit(chart);cg.clearRect(0,0,w,h);cg.strokeStyle='#24313c';cg.lineWidth=1;for(let y=15;y<h;y+=30){cg.beginPath();cg.moveTo(18,y);cg.lineTo(w-18,y);cg.stroke()}for(const [key,color]of [['sensory','#60dfc5'],['integration','#a195ef'],['motor','#f5b077']]){cg.beginPath();sim.history.forEach((v,i)=>{const x=18+(v.t-sim.time+20)/20*(w-36),y=h-8-v[key]*(h-22);i?cg.lineTo(x,y):cg.moveTo(x,y)});cg.strokeStyle=color;cg.lineWidth=1.5;cg.stroke()}}
function renderUI(){for(const [id]of sensory){$('#bar-'+id).style.width=sim.sensors[id]*100+'%';$('#val-'+id).textContent=sim.sensors[id].toFixed(2)}for(const id of ['left','right']){$('#bar-'+id).style.width=sim.motor[id]*100+'%';$('#val-'+id).textContent=sim.motor[id].toFixed(2)}$('#timer').textContent=time(sim.time,true);$('#velocity').textContent=sim.fly.speed.toFixed(1);$('#turn').textContent=(sim.fly.turn*180/Math.PI).toFixed(1);$('#behavior').textContent=names[sim.reason];
 const chain={explore:['Фоновый вход','Исследование'],food:['Запах','Ориентация'],light:['Свет','Ориентация'],escape:['LC4*','DNp01* '+sim.dn.toFixed(2)],touch:['Касание','Избегание'],barrier:['Близость','Обход'],eat:['Еда достигнута','Остановка']}[sim.reason];$('#circuit').innerHTML=`<span>${chain[0]}</span><b>→</b><span>${chain[1]}</span>`;
 const details={explore:'Сильного стимула нет. Фоновый сигнал меняет направление исследования.',food:`Градиент запаха (${sim.sensors.odor.toFixed(2)}) направляет агента к ближайшей еде.`,light:'Источник справа вверху задаёт направление положительного фототаксиса в модели.',escape:`Зрительный вход LC4* (${sim.sensors.vision.toFixed(2)}) активирует DNp01* (${sim.dn.toFixed(2)}). Сигнал избегания сильнее притяжения.`,touch:'Тактильный импульс имеет приоритет: агент отворачивается от точки касания.',barrier:sim.collision?'Граница блокирует поступательное движение. Моторная команда разворачивает агента.':'Близкий барьер или край арены задаёт направление обхода.',eat:'Источник еды достигнут. Модель делает короткую остановку.'};
 const turn=Math.abs(sim.fly.turn)<.08?'Каналы почти сбалансированы.':`${sim.motor.left>sim.motor.right?'Левый':'Правый'} моторный канал сильнее: поворот ${sim.fly.turn>0?'вправо':'влево'}.`;$('#explanation').textContent=details[sim.reason]+' '+turn+(sim.sensors.heat>.1?' Тепловой стресс снижает скорость.':'');if(sim.notice){log(sim.notice);sim.notice=null}}
function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left-ox)/scale,y:(e.clientY-r.top-oy)/scale}}
function applyAt(p){if(p.x<0||p.x>W||p.y<0||p.y>H)return;log(sim.place(tool,p.x,p.y));pulse={...p,t:performance.now()};draw()}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.focus();applyAt(point(e))});canvas.addEventListener('pointermove',e=>cursor=point(e));canvas.addEventListener('pointerleave',()=>cursor=null);canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key)){e.preventDefault();cursor??={x:sim.fly.x,y:sim.fly.y};if(e.key==='Enter')applyAt(cursor);else{cursor.x=clamp(cursor.x+(e.key==='ArrowLeft'?-20:e.key==='ArrowRight'?20:0),0,W);cursor.y=clamp(cursor.y+(e.key==='ArrowUp'?-20:e.key==='ArrowDown'?20:0),0,H)}}});
window.addEventListener('keydown',e=>{if(modal.open||['INPUT','BUTTON','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();setPaused(!paused)}if('12345'.includes(e.key)&&e.key.length===1)selectTool(['food','obstacle','touch','object','erase'][Number(e.key)-1])});
document.addEventListener('visibilitychange',()=>{last=0;acc=0});
function frame(now){if(last&&!paused&&!document.hidden){acc+=Math.min((now-last)/1000,.1)*speed;while(acc>=1/60){sim.step(1/60);acc-=1/60}}last=now;if(now-lastUI>90){renderUI();lastUI=now}draw();requestAnimationFrame(frame)}
