register({name:'read_arena',description:'Прочитать состояние модельной арены и моторные команды.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return {time:sim.time,paused,temperature:sim.temperature,light:sim.light,predator:sim.predator,fly:{...sim.fly},sensors:{...sim.sensors},motor:{...sim.motor},behavior:names[sim.reason],objects:sim.objects.map(o=>({...o})),modelOnly:true}}});
